import {defineConfig, globalIgnores} from 'eslint/config'
import js from '@eslint/js'
import tseslint from 'typescript-eslint'
import stylistic from '@stylistic/eslint-plugin'
import globals from 'globals'

export default defineConfig([
    //The source of TypeORM in @lakutata/orm keeps the style of TypeORM, merged from its repository (packages/orm/vendor/typeorm)
    globalIgnores(['**/node_modules/', '**/dist/', '**/distro/', 'proposal/', 'consumer-fixture/.examples/', 'packages/orm/vendor/typeorm/',
        //Generated by the website: the entry points of its API reference, the cache of VitePress
        'website/.api/', 'website/src/.vitepress/cache/']),
    {
        files: ['**/*.ts', '**/*.mts', '**/*.cts'],
        extends: [js.configs.recommended, tseslint.configs.recommended],
        plugins: {
            '@stylistic': stylistic
        },
        languageOptions: {
            ecmaVersion: 'latest',
            sourceType: 'module',
            globals: globals.node,
            //The type information of the files, from the tsconfig.json of their package
            parserOptions: {
                projectService: true,
                tsconfigRootDir: import.meta.dirname
            }
        },
        rules: {
            //A promise is awaited, returned or handled: a rejection nothing handles ends the process
            '@typescript-eslint/no-floating-promises': ['error', {
                allowForKnownSafeCalls: [{
                    from: 'package',
                    package: 'node:test',
                    name: ['describe', 'it', 'test', 'suite', 'before', 'after', 'beforeEach', 'afterEach', 'skip', 'todo', 'only']
                }]
            }],
            '@typescript-eslint/no-misused-promises': 'error',
            '@typescript-eslint/await-thenable': 'error',
            //The style: single quotes (other quotes only to avoid escaping), no semicolons, no trailing commas
            '@stylistic/quotes': ['error', 'single', {avoidEscape: true, allowTemplateLiterals: 'always'}],
            '@stylistic/semi': ['error', 'never'],
            '@stylistic/comma-dangle': ['error', 'never'],
            '@stylistic/no-extra-semi': 'error',
            //The members of the types: one per line without delimiter, or on one line separated by commas
            '@stylistic/member-delimiter-style': ['error', {
                multiline: {delimiter: 'none'},
                singleline: {delimiter: 'comma', requireLast: false}
            }],
            //A destructuring is const when all its variables are
            'prefer-const': ['error', {destructuring: 'all'}],
            //An import of a module per file (the type imports inline: import {type A, B})
            'no-duplicate-imports': 'error',
            //@ts-ignore keeps ignoring once the error is gone, @ts-expect-error fails then: it is used with its reason
            '@typescript-eslint/ban-ts-comment': ['error', {
                'ts-ignore': true,
                'ts-nocheck': true,
                'ts-expect-error': 'allow-with-description'
            }],
            //The parameters kept for a signature start with an underscore, the variables of a destructuring may only
            //leave their properties out of its rest
            '@typescript-eslint/no-unused-vars': ['error', {
                argsIgnorePattern: '^_',
                varsIgnorePattern: '^_',
                caughtErrors: 'none',
                ignoreRestSiblings: true
            }],
            //The framework relies on these constructs
            'prefer-spread': 'off',
            'prefer-rest-params': 'off',
            'no-constant-condition': 'off',
            'no-control-regex': 'off',
            'no-useless-escape': 'off',
            '@typescript-eslint/no-explicit-any': 'off',
            '@typescript-eslint/no-namespace': 'off',
            '@typescript-eslint/no-this-alias': 'off',
            '@typescript-eslint/no-unnecessary-type-constraint': 'off',
            '@typescript-eslint/no-unsafe-function-type': 'off',
            '@typescript-eslint/no-empty-object-type': 'off',
            '@typescript-eslint/no-wrapper-object-types': 'off',
            '@typescript-eslint/no-unused-expressions': ['error', {allowShortCircuit: true, allowTernary: true}]
        }
    },
    {
        //The test suites ported from the upstream libraries are not type checked
        files: ['**/tests/**/*.ts'],
        rules: {
            '@typescript-eslint/ban-ts-comment': ['error', {
                'ts-ignore': true,
                'ts-nocheck': false,
                'ts-expect-error': 'allow-with-description'
            }]
        }
    },
    {
        //The templates of the projects are not in the TypeScript projects of the packages
        files: ['packages/template-*/template/**'],
        ...tseslint.configs.disableTypeChecked
    },
    {
        //The blocks of the features of the templates (//@if <feature> … //@else … //@end) are alternatives of the same
        //code: a project created has one of them
        files: ['packages/template-*/template/**'],
        rules: {
            'no-duplicate-imports': 'off',
            'no-useless-assignment': 'off'
        }
    },
    {
        //The browser entry of the WebRTC package, and the code it shares with the main entry: the APIs of the browsers
        //only, nothing of Node.js or of the framework, so a frontend bundling it gets no server code
        files: ['packages/webrtc/src/client/**/*.ts', 'packages/webrtc/src/shared/**/*.ts', 'packages/webrtc/src/protocol/**/*.ts'],
        languageOptions: {
            globals: globals.browser
        },
        rules: {
            'no-restricted-imports': ['error', {
                patterns: [
                    {regex: '^node:', message: 'The browser entry may not use the modules of Node.js'},
                    {regex: '^@lakutata/', message: 'The browser entry may not use the framework'}
                ]
            }]
        }
    },
    {
        //The test suites of the validation engine are ported from joi as they are
        files: ['packages/core/src/tests/engine/**/*.ts'],
        rules: {
            '@typescript-eslint/no-unused-vars': 'off'
        }
    },
    {
        files: ['**/*.js', '**/*.mjs', '**/*.cjs'],
        extends: [js.configs.recommended],
        plugins: {
            '@stylistic': stylistic
        },
        languageOptions: {
            ecmaVersion: 'latest',
            sourceType: 'module',
            globals: globals.node
        },
        rules: {
            '@stylistic/quotes': ['error', 'single', {avoidEscape: true, allowTemplateLiterals: 'always'}],
            '@stylistic/semi': ['error', 'never'],
            '@stylistic/comma-dangle': ['error', 'never']
        }
    }
])
